return {["scripts/items/ascention.lua"]={["Path"]="scripts/items/ascention.lua",["SHA256"]="fab698d708aeffaa0ca0d09d4937d40bafa4a5d9e8dd796ccc9a583ef8599b2b",["Text"]="-----------------------------------\n-- ID: 18042\n-- Item: Ascention\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    if target:getEcosystem() ~= xi.ecosystem.UNDEAD then\n        return 0, 0, 0\n    end\n\n    local dStat  = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT) -- Is this MND vs MND?\n    local power  = 10 + utils.clamp(math.floor(dStat / 1.5), 0, 55) -- Somewhat approximate. It looks like x/256 madness is going on\n    local pTable =\n    {\n        chance         = 100,\n        basePower      = math.randomInt(power, power + 5), -- Upper range is sometimes not +5, but this is good enough.\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/assailants_axe.lua"]={["Path"]="scripts/items/assailants_axe.lua",["SHA256"]="641efa27cbe3906b04fa7ed09d68c6592a69c0033d1aba21d2585c348965a9f6",["Text"]="-----------------------------------\n-- ID: 18488\n-- Item: assailants_axe\n-- Item Effect: Acc +3\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ASSAILANTS_AXE) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ASSAILANTS_AXE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.ASSAILANTS_AXE) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.ASSAILANTS_AXE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ACC, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/assassins_ring.lua"]={["Path"]="scripts/items/assassins_ring.lua",["SHA256"]="72c43c46312ba48947c89df39760f55f1e636ff4e2729f3b930f1e899964c34f",["Text"]="-----------------------------------\n-- ID: 14678\n-- Item: Assassin's Ring\n-- Item Effect: Ranged Accuracy 20\n-- Duration: 5 Minutes\n-- https://wiki.ffo.jp/html/10071.html\n-- TODO: Capture icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.ASSASSINS_RING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ASSASSINS_RING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 300, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.ASSASSINS_RING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.RACC, 20)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ASSASSINS_RING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/astral_cube.lua"]={["Path"]="scripts/items/astral_cube.lua",["SHA256"]="867a1e6cc4ec9d841997bca21887dfa2c7d3cc77cdeaf01035c1b1d91e83e5a0",["Text"]="-----------------------------------\n-- ID: 6413\n-- Item: Astral Cube\n-- Item Effect: Grant Astral cube key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.ASTRAL_CUBE\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, xi.item.ASTRAL_CUBE, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/astral_pot.lua"]={["Path"]="scripts/items/astral_pot.lua",["SHA256"]="b1c827fa6ca70ed547555d8de87529c7349e0961b6176972ab359c8a686bd6c7",["Text"]="-----------------------------------\n-- ID: 18243\n-- Item: Astral Pot\n-- Item Effect: Pet Magical Attack +10\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/10083.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local pet = target:getPet()\n    if not pet then\n        return xi.msg.basic.REQUIRES_A_PET, 0\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local pet = target:getPet()\n    if not pet then\n        return\n    end\n\n    if target:hasEquipped(xi.item.ASTRAL_POT) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ASTRAL_POT)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.ASTRAL_POT })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local pet = target:getPet()\n    if not pet then\n        return\n    end\n\n    pet:addMod(xi.mod.MATT, 10)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ASTRAL_POT)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    local pet = target:getPet()\n    if not pet then\n        return\n    end\n\n    pet:delMod(xi.mod.MATT, 10)\nend\n\nreturn itemObject\n"},["scripts/items/augmenting_belt.lua"]={["Path"]="scripts/items/augmenting_belt.lua",["SHA256"]="d23e5e04ccee174f23a433a9e82774d14821e03afb3ff11ecd2312901b5afe37",["Text"]="-----------------------------------\n-- ID: 15889\n-- Item: augmenting_belt\n-- Item Effect: HPHEAL +2\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.AUGMENTING_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.AUGMENTING_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.AUGMENTING_BELT) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.AUGMENTING_BELT })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/aurorastorm_schema.lua"]={["Path"]="scripts/items/aurorastorm_schema.lua",["SHA256"]="fc1de4bc23e09603cfc48919b73d1d2227eeef92c48dc82176457cf054800614",["Text"]="-----------------------------------\n-- ID: 6055\n-- Item: Aurorastorm Schema\n-- Teaches the white magic Aurorastorm\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.AURORASTORM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.AURORASTORM)\nend\n\nreturn itemObject\n"},["scripts/items/austers_staff.lua"]={["Path"]="scripts/items/austers_staff.lua",["SHA256"]="2a0b8e2d4b5388134e0e1d0ae3efe961c293d825bf3aa33c1560dcdbdc4545d4",["Text"]="-----------------------------------\n-- ID: 17550\n-- Item: Auster's Staff\n-- Additional effect: wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 25, -- guessed\n        basePower      = math.randomInt(25, 34),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/avengers_die.lua"]={["Path"]="scripts/items/avengers_die.lua",["SHA256"]="1768ae6a43cc7ac2813a9948d34277f6456814e5c0901d772acd1dfbe0bfcb57",["Text"]="-----------------------------------\n-- ID: 5505\n-- Avenger's Die\n-- Teaches the job ability Avengers Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.AVENGERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.AVENGERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/b.e.w._pitaru.lua"]={["Path"]="scripts/items/b.e.w._pitaru.lua",["SHA256"]="352d3e86e0f2f46e6954ccb23d9e3706815caca7ef5e166bf1c23273ad47c27f",["Text"]="-----------------------------------\n-- ID: 5892\n-- Item: b.e.w._pitaru\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- MP +9% (cap 130)\n-- Increases rate of magic skill gains by 80%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 9)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 130)\n    effect:addMod(xi.mod.MAGIC_SKILLUP_RATE, 80)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bag_of_wyvern_feed.lua"]={["Path"]="scripts/items/bag_of_wyvern_feed.lua",["SHA256"]="1d9f1d11cc027f5d6d36b16ba1f78a9b9f9a190c7dcc01dac0caf42f6cde1f72",["Text"]="-----------------------------------\n-- ID: 18242\n-- Item: Wyvern Feed\n-- Item Effect: Pet Regen\n-- Duration: 60 Seconds\n-- https://wiki.ffo.jp/html/10082.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local pet    = target:getPet()\n\n    if not pet then\n        return xi.msg.basic.REQUIRES_A_PET, 0\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local pet = target:getPet()\n    if target:hasEquipped(xi.item.BAG_OF_WYVERN_FEED) and pet then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.BAG_OF_WYVERN_FEED)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.BAG_OF_WYVERN_FEED })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local pet = target:getPet()\n    if not pet then\n        return\n    end\n\n    pet:addMod(xi.mod.REGEN, 12)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.BAG_OF_WYVERN_FEED)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    local pet = target:getPet()\n    if not pet then\n        return\n    end\n\n    pet:delMod(xi.mod.REGEN, 12)\nend\n\nreturn itemObject\n"},["scripts/items/bahadur.lua"]={["Path"]="scripts/items/bahadur.lua",["SHA256"]="0ab413ab3d654649190f399d44cefae3c54f6c1a941f2a1bf6462c483337fcd3",["Text"]="-----------------------------------\n-- ID: 19151\n-- Item: Bahadur\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7.5, -- TODO: looks like it might scale with INT?\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bahadur_+1.lua"]={["Path"]="scripts/items/bahadur_+1.lua",["SHA256"]="1bed3bd13059fc629de15644e6f8385fe31138951dfebd44772d765ee3ff6167",["Text"]="-----------------------------------\n-- ID: 19152\n-- Item: Bahadur +1\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7.5, -- TODO: looks like it might scale with INT?\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/baked_apple.lua"]={["Path"]="scripts/items/baked_apple.lua",["SHA256"]="d8587e64548b7a8824b464b021ee821d54905bccc34c1f67e4194dcfaed092a9",["Text"]="-----------------------------------\n-- ID: 4406\n-- Item: Baked Apple\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 20\n-- Agility -1\n-- Intelligence 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.INT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/baked_popoto.lua"]={["Path"]="scripts/items/baked_popoto.lua",["SHA256"]="953e3c3cda71d023747061c431fed9e278285e58dd553d58a32f69385ad6534e",["Text"]="-----------------------------------\n-- ID: 4436\n-- Item: Baked Popoto\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 20\n-- Dexterity -1\n-- Vitality 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = us