em, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.RACC, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/balik_sis.lua"]={["Path"]="scripts/items/balik_sis.lua",["SHA256"]="7afd019a3e7d867389be6db601e38987be732abe35c4bced8bbb506170ad4be4",["Text"]="-----------------------------------\n-- ID: 5600\n-- Item: Balik Sis\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 4\n-- Mind -2\n-- Attack % 13\n-- Attack Cap 65\n-- Ranged ACC 1\n-- Ranged ATT % 13\n-- Ranged ATT Cap 65\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 13)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 65)\n    effect:addMod(xi.mod.RACC, 1)\n    effect:addMod(xi.mod.FOOD_RATTP, 13)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 65)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/balik_sis_+1.lua"]={["Path"]="scripts/items/balik_sis_+1.lua",["SHA256"]="809cbf898bc8636b8b8ca3680d27d8a3d7705227a009da4235930f21876f0a1e",["Text"]="-----------------------------------\n-- ID: 5601\n-- Item: Balik Sis +1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Dexterity 5\n-- Mind -2\n-- Attack % 15\n-- Attack Cap 70\n-- Ranged ACC 2\n-- Ranged ATT % 15\n-- Ranged ATT Cap 70\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 5)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 15)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 70)\n    effect:addMod(xi.mod.RACC, 2)\n    effect:addMod(xi.mod.FOOD_RATTP, 15)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 70)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/balmung.lua"]={["Path"]="scripts/items/balmung.lua",["SHA256"]="26cc43fc832a26da093339e094fda5a2a4aa6e4cd36e072b16a3334f5c9bfcc7",["Text"]="-----------------------------------\n-- ID: 16942\n-- Item: Balmung\n-- Additional effect: Dispel\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 10,\n        magicalElement = xi.element.DARK,\n    }\n\n    return xi.combat.action.executeAddEffectDispel(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bannaret_mail.lua"]={["Path"]="scripts/items/bannaret_mail.lua",["SHA256"]="8e4b73ad8533fe973976f4a5c0686ee43888e8121d67e6c599561b4625d33579",["Text"]="-----------------------------------\n-- ID: 14531\n-- Item: bannaret_mail\n-- Item Effect: HP +15, Enmity +2\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.BANNARET_MAIL) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.BANNARET_MAIL)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.BANNARET_MAIL) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.BANNARET_MAIL })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HP, 15)\n    effect:addMod(xi.mod.ENMITY, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bano_del_sol.lua"]={["Path"]="scripts/items/bano_del_sol.lua",["SHA256"]="3d3fa63540976a37267ddbdd73ae09d9b68e3d60d5c221dfc3bf4e891ff70a08",["Text"]="-----------------------------------\n-- ID: 17981\n-- Item: Bano Del Sol\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local species = target:isMob() and target:getSpecies() or xi.mobSpecies.UNCLASSIFIED\n\n    if species ~= xi.mobSpecies.SLIME and species ~= xi.mobSpecies.CLOT then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance         = 10, -- TODO: this probably scales with dINT but sample sizes are insanely low.\n        basePower      = math.randomInt(39, 42),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bar_of_campfire_chocolate.lua"]={["Path"]="scripts/items/bar_of_campfire_chocolate.lua",["SHA256"]="86094c31372c4e129be31738bdb2c8448c6fd98e473e666eb5113174c15a3226",["Text"]="-----------------------------------\n-- ID: 5941\n-- Item: Bar of Campfire Chocolate\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Mind +1\n-- MP recovered while healing +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bard_die.lua"]={["Path"]="scripts/items/bard_die.lua",["SHA256"]="ddc132fe411fb1bb82a92c85887ff53463cbfea50481aa263714f963661b1d37",["Text"]="-----------------------------------\n-- ID: 5486\n-- Bard Die\n-- Teaches the job ability Choral Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.CHORAL_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.CHORAL_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/bartholomews_knife.lua"]={["Path"]="scripts/items/bartholomews_knife.lua",["SHA256"]="8446924b6a9710cc1039b0f7e4da0d75f00109b426a7792c69cee5719653b827",["Text"]="-----------------------------------\n-- ID: 17623\n-- Item: Bartholomew's Knife\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 10,\n        basePower      = math.max(0, math.randomInt(dStat, dStat + 5)), -- Unlimited scaling?\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bastok_markets_gate_glyph.lua"]={["Path"]="scripts/items/bastok_markets_gate_glyph.lua",["SHA256"]="f9d43b550586a657812b0c3ded0f204dfc10826feccb9b7aafbedbcfbbaa7adb",["Text"]="-----------------------------------\n-- ID: 4188\n-- Bastok Markets Gate Glyph\n-- Transports the user to the Bastok Markets gate\n-- (near Rabid Wolf, I.M.)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.BASTOK_MARKETS_GLYPH, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/bastok_mines_gate_glyph.lua"]={["Path"]="scripts/items/bastok_mines_gate_glyph.lua",["SHA256"]="f54fc2a749ca07428eddbd2789c16b8867ee9a0292cd5b4f5fa0c98a7d58f9ad",["Text"]="-----------------------------------\n-- ID: 4187\n-- Bastok Mines Gate Glyph\n-- Transports the user to the Bastok Mines gate\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.BASTOK_MINES_GLYPH, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/bastore_bream.lua"]={["Path"]="scripts/items/bastore_bream.lua",["SHA256"]="1f6e2e48996dbb8323cfc3efb078e80854ef8979b7bbb0b65cdff79e755dabdf",["Text"]="-----------------------------------\n-- ID: 4461\n-- Item: Bastore Bream\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 4\n-- Mind -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bastore_sardine.lua"]={["Path"]="scripts/items/bastore_sardine.lua",["SHA256"]="7b5dfb78758180efe641157a9f1ebeb94997ac11345b6e116a9b10cc2ae87c46",["Text"]="-----------------------------------\n-- ID: 5792\n-- Item: Bastore Sardine\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 1\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.MND, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bastore_sweeper.lua"]={["Path"]="scripts/items/bastore_sweeper.lua",["SHA256"]="3ae2be858228c09e46a7871b64e4d161cb64fcdfe7f77a095d7c84f43d1b8440",["Text"]="-----------------------------------\n-- ID: 5473\n-- Item: Bastore Sweeper\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality +3\n-- Defense +15% Cap 50\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_DEFP, 15)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bataquiche.lua"]={["Path"]="scripts/items/bataquiche.lua",["SHA256"]="61d5450927b3bdc66d175f066d57ff8cc77ca2a191ce9e42c1201fc1d393dd2b",["Text"]="-----------------------------------\n-- ID: 5168\n-- Item: Bataquiche\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 8\n-- Agility 1\n-- Vitality -2\n-- Ranged Acc % 7\n-- Ranged Acc Cap 15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 8)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -2)\n    effect:addMod(xi.mod.FOOD_RACCP, 7)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bataquiche_+1.lua"]={["Path"]="scripts/items/bataquiche_+1.lua",["SHA256"]="6f6616ddcee81678686a33dd4412ba0e4d114cc4e66467799fcee0489ddce1f7",["Text"]="-----------------------------------\n-- ID: 5169\n-- Item: Bataquiche +1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Magic 10\n-- Agility 1\n-- Vitality -1\n-- Ranged Acc % 7\n-- Ranged Acc Cap 20\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.FOOD_RACCP, 7)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/battle_fork.lua"]={["Path"]="scripts/items/battle_fork.lua",["SHA256"]="bab80fb50ec1b97b541cd5b0ad625dddb1f37c2c9f2065050b09a12a595499fe",["Text"]="-----------------------------------\n-- ID: 16888\n-- Item: Battle Fork\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 15 + utils.clamp(dStat / 3, 0, 18), -- 15 + 0-18% over 54 dINT, approx.\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/battle_fork_+1.lua"]={["Path"]="scripts/items/battle_fork_+1.lua",["SHA256"]="3f5ebbc0702013b26fc52d7dd6bb4819f9f91d17efafe2e808f0d3ef688bc26f",["Text"]="-----------------------------------\n-- ID: 16889\n-- Item: Battle Fork +1\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 15 + utils.clamp(dStat / 3, 0, 18), -- 15 + 0-18% over 54 dINT, approx.\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bead_pouch.lua"]={["Path"]="scripts/items/bead_pouch.lua",["SHA256"]="ceb43c3238ac670f851d8de0f4bd5d92b46612c6d96a4733ab94d662e6058184",["Text"]="-----------------------------------\n-- ID: 6392\n-- Bead Pouch\n-- Bead Pouch awards 5-10 beads on use.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local amount = math.randomInt(5, 10)\n    target:messageCombat(target, xi.item.BEAD_POUCH, amount, xi.msg.basic.USE_OBTAIN_ESCHA_BEAD)\n    target:addCurrency('escha_beads', amount)\nend\n\nreturn itemObject\n"},["scripts/items/beaming_score.lua"]={["Path"]="scripts/items/beaming_score.lua",["SHA256"]="211ed1b0e0144accdde1cd004edffa4b42675431a38ed686947393808b5e9b6c",["Text"]="-----------------------------------\n-- ID: 6174\n-- Item: Beaming Score\n-- A musical score composed by Lewenhart.\n-- Its notes symbolize the gently glowing beams of light that filter through the leaves of a deciduous tree in the late afternoon.\n-- Adventurers note that reading it increases one's wind instrument skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.WIND_INSTRUMENT)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.WIND_INSTRUMENT)\nend\n\nreturn itemObject\n"},["scripts/items/bean_daifuku.lua"]={["Path"]="scripts/items/bean_daifuku.lua",["SHA256"]="b98289c036981e4f61cb74fcf538edf1d87c36d3f2066c01bed801faff9280e7",["Text"]="-----------------------------------\n-- ID: 6341\n-- Item: bean_daifuku\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- HP +20\n-- VIT +5\n-- Accuracy +10% (cap 80)\n-- Ranged Accuracy +10% (cap 80)\n-- Pet:\n-- HP +20\n-- VIT +5\n-- Accuracy +10% (cap 105)\n-- Ranged Accuracy +10% (cap 105)\n-- Defense +10% (cap 100)\n-- Haste +3%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.VIT, 5)\n    effect:addMod(xi.mod.FOOD_ACCP, 10)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RACCP, 10)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    target:addPetMod(xi.mod.FOOD_HP, 20)\n    target:addPetMod(xi.mod.VIT, 5)\n    target:addPetMod(xi.mod.FOOD_ACCP, 10)\n    target:addPetMod(xi.mod.FOOD_ACC_CAP, 105)\n    target:addPetMod(xi.mod.FOOD_RACCP, 10)\n    target:addPetMod(xi.mod.FOOD_RACC_CAP, 105)\n    target:addPetMod(xi.mod.FOOD_DEFP, 10)\n    target:addPetMod(xi.mod.FOOD_DEF_CAP, 100)\n    target:addPetMod(xi.mod.HASTE_GEAR, 300)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.FOOD_HP, 20)\n    target:delPetMod(xi.mod.VIT, 5)\n    target:delPetMod(xi.mod.FOOD_ACCP, 10)\n    target:delPetMod(xi.mod.FOOD_ACC_CAP, 105)\n    target:delPetMod(xi.mod.FOOD_RACCP, 10)\n    target:delPetMod(xi.mod.FOOD_RACC_CAP, 105)\n    target:delPetMod(xi.mod.FOOD_DEFP, 10)\n    target:delPetMod(xi.mod.FOOD_DEF_CAP, 100)\n    target:delPetMod(xi.mod.HASTE_GEAR, 300)\nend\n\nreturn itemObject\n"},["scripts/items/bean_daifuku_+1.lua"]={["Path"]="scripts/items/bean_daifuku_+1.lua",["SHA256"]="f04dcbd5641cac5a8b84a25b3dcc870d62a4e26a466a1a7c8c650f636e14b2b1",["Text"]="-----------------------------------\n-- ID: 6342\n-- Item: bean_daifuku_+1\n-- Food Effect: 60 Min, All Races\n-----------------------------------\n-- HP +30\n-- VIT +7\n-- Accuracy +11% (cap 85)\n-- Ranged Accuracy +11% (cap 85)\n-- Pet:\n-- HP +30\n-- VIT +7\n-- Accuracy +11% (cap 110)\n-- Ranged Accuracy +11% (cap 110)\n-- Defense +11% (cap 105)\n-- Haste +4%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.VIT, 7)\n    effect:addMod(xi.mod.FOOD_ACCP, 11)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 85)\n    effect:addMod(xi.mod.FOOD_RACCP, 11)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 85)\n    target:addPetMod(xi.mod.FOOD_HP, 30)\n    target:addPetMod(xi.mod.VIT, 7)\n    target:addPetMod(xi.mod.FOOD_ACCP, 11)\n    target:addPetMod(xi.mod.FOOD_ACC_CAP, 110)\n    target:addPetMod(xi.mod.FOOD_RACCP, 11)\n    target:addPetMod(xi.mod.FOOD_RACC_CAP, 110)\n    target:addPetMod(xi.mod.FOOD_DEFP, 11)\n    target:addPetMod(xi.mod.FOOD_DEF_CAP, 105)\n    target:addPetMod(xi.mod.HASTE_GEAR, 400)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.FOOD_HP, 30)\n    target:delPetMod(xi.mod.VIT, 7)\n    target:delPetMod(xi.mod.FOOD_ACCP, 11)\n    target:delPetMod(xi.mod.FOOD_ACC_CAP, 110)\n    target:delPetMod(xi.mod.FOOD_RACCP, 11)\n    target:delPetMod(xi.mod.FOOD_RACC_CAP, 110)\n    target:delPetMod(xi.mod.FOOD_DEFP, 11)\n    target:delPetMod(xi.mod.FOOD_DEF_CAP, 105)\n    target:delPetMod(xi.mod.HASTE_GEAR, 400)\nend\n\nreturn itemObject\n"},["scripts/items/beastmaster_die.lua"]={["Path"]="scripts/items/beastmaster_die.lua",["SHA256"]="2723a31c9094e6833e38c6b537c1d05918d4c6ecc84a8235acf9a7072417ced8",["Text"]="-----------------------------------\n-- ID: 5485\n-- Beastmaster Die\n-- Teaches the job ability Beast Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.BEAST_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.BEAST_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/beef_stewpot.lua"]={["Path"]="scripts/items/beef_stewpot.lua",["SHA256"]="6c7699a4870803e205ce2ad47226d9192903bca975c1e79183dcf2030ef979d0",["Text"]="-----------------------------------\n-- ID: 5547\n-- Item: Beef Stewpot\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +10% Cap 50\n-- MP +10\n-- HP Recoverd while healing 5\n-- MP Recovered while healing 1\n-- Attack +18% Cap 40\n-- Evasion +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 50)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.HPHEAL, 5)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/beetle_quiver.lua"]={["Path"]="scripts/items/beetle_quiver.lua",["SHA256"]="dde9daaa4820791d4e4a78bd30b13637555991bcfbd2647c61348d1bea550276",["Text"]="-----------------------------------\n-- ID: 4221\n-- Item: Beetle Quiver\n-- When used, you will obtain one stack of Beetle Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BEETLE_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/behemoth_steak.lua"]={["Path"]="scripts/items/behemoth_steak.lua",["SHA256"]="76063d05af9fcebaf6f94536a41e28b0c73044fa29ccc3fdaa1df0ec391b9032",["Text"]="-----------------------------------\n-- ID: 6464\n-- Item: behemoth_steak\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- HP +40\n-- STR +7\n-- DEX +7\n-- INT -3\n-- Attack +23% (cap 160)\n-- Ranged Attack +23% (cap 160)\n-- Triple Attack +1%\n-- Lizard Killer +4\n-- hHP +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 40)\n    effect:addMod(xi.mod.STR, 7)\n    effect:addMod(xi.mod.DEX, 7)\n    effect:addMod(xi.mod.INT, -3)\n    effect:addMod(xi.mod.FOOD_ATTP, 23)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 160)\n    effect:addMod(xi.mod.FOOD_RATTP, 23)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 160)\n    effect:addMod(xi.mod.TRIPLE_ATTACK, 1)\n    effect:addMod(xi.mod.LIZARD_KILLER, 4)\n    effect:addMod(xi.mod.HPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/behemoth_steak_+1.lua"]={["Path"]="scripts/items/behemoth_steak_+1.lua",["SHA256"]="a090ac300c3c022c8a1d801206fa980bbca0c88cd57377cbb3403841efaf551d",["Text"]="-----------------------------------\n-- ID: 6465\n-- Item: behemoth_steak_+1\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- HP +45\n-- STR +8\n-- DEX +8\n-- INT -4\n-- Attack +24% (cap 165)\n-- Ranged Attack +24% (cap 165)\n-- Triple Attack +2%\n-- Lizard Killer +5\n-- hHP +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 45)\n    effect:addMod(xi.mod.STR, 8)\n    effect:addMod(xi.mod.DEX, 8)\n    effect:addMod(xi.mod.INT, -4)\n    effect:addMod(xi.mod.FOOD_ATTP, 24)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 165)\n    effect:addMod(xi.mod.FOOD_RATTP, 24)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 165)\n    effect:addMod(xi.mod.TRIPLE_ATTACK, 2)\n    effect:addMod(xi.mod.LIZARD_KILLER, 5)\n    effect:addMod(xi.mod.HPHEAL, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/behemoth_suit_+1.lua"]={["Path"]="scripts/items/behemoth_suit_+1.lua",["SHA256"]="c7b03e464f21cd5ff3f3bd38a3075502be43bade3011964c07972575edb12afe",["Text"]="-----------------------------------\n--  ID: 26955\n--  Behemoth Suit +1\n--  When used, player will obtain one of sixteen random meats or with very low\n--  chance either a Beastly or Savory Shank. Possible Normal meats are:\n--  Buffalo Meat, Cerberus Meat, Cockatrice Meat, Coeurl Meat, Dhalmel Meat,\n--  Dragon Meat, Giant Sheep Meat, Hare Meat, Hydra Meat, Karakul Meat,\n--  Land Crab Meat, Lucerewe Meat, Lynx Meat, Orobon Meat, Ruszor Meat,\n--  Ziz Meat - Data capture 2022-05\n--  Chance of obtaining a Beastly or Savory Shank is very low.\n--  2/164 Beastly Shank\n--  0/164 Savory Shank\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    local meatList =\n    {\n        { itemId = xi.item.SLICE_OF_BUFFALO_MEAT,     weight =  9 },\n        { itemId = xi.item.SLICE_OF_CERBERUS_MEAT,    weight =  4 },\n        { itemId = xi.item.SLICE_OF_COCKATRICE_MEAT,  weight = 17 },\n        { itemId = xi.item.SLICE_OF_COEURL_MEAT,      weight = 13 },\n        { itemId = xi.item.SLICE_OF_DHALMEL_MEAT,     weight = 20 },\n        { itemId = xi.item.SLICE_OF_DRAGON_MEAT,      weight =  5 },\n        { itemId = xi.item.SLICE_OF_GIANT_SHEEP_MEAT, weight = 17 },\n        { itemId = xi.item.SLICE_OF_HARE_MEAT,        weight = 22 },\n        { itemId = xi.item.CHUNK_OF_HYDRA_MEAT,       weight =  5 },\n        { itemId = xi.item.SLICE_OF_KARAKUL_MEAT,     weight =  4 },\n        { itemId = xi.item.SLICE_OF_LAND_CRAB_MEAT,   weight =  9 },\n        { itemId = xi.item.SLICE_OF_LUCEREWE_MEAT,    weight =  7 },\n        { itemId = xi.item.LYNX_MEAT,                 weight =  5 },\n        { itemId = xi.item.CHUNK_OF_OROBON_MEAT,      weight =  9 },\n        { itemId = xi.item.SLAB_OF_RUSZOR_MEAT,       weight =  9 },\n        { itemId = xi.item.SLICE_OF_ZIZ_MEAT,         weight =  7 },\n        { itemId = xi.item.BEASTLY_SHANK,             weight =  2 },\n        -- { ?, xi.item.SAVORY_SHANK },\n    }\n\n    npcUtil.giveItem(target, { { xi.itemUtils.pickItemRandom(meatList), 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/beitetsu_box.lua"]={["Path"]="scripts/items/beitetsu_box.lua",["SHA256"]="75d5f855754247af034c94cfbd9375c6e741553ef0c864fe1b13bfa0f831bd47",["Text"]="-----------------------------------\n-- ID: 6184\n-- Beitetsu Box\n-- Breaks up a Beitetsu Box\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BEITETSU, math.randomInt(15, 30) } })\nend\n\nreturn itemObject\n"},["scripts/items/beitetsu_parcel.lua"]={["Path"]="scripts/items/beitetsu_parcel.lua",["SHA256"]="cf4578156f4f9332c2198c93a1a4d985a130f5373747a46eef4d3e70518fb3f3",["Text"]="-----------------------------------\n-- ID: 6181\n-- Beitetsu Parcel\n-- Breaks up a Beitetsu Parcel\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BEITETSU, math.randomInt(3, 15) } })\nend\n\nreturn itemObject\n"},["scripts/items/beluga.lua"]={["Path"]="scripts/items/beluga.lua",["SHA256"]="13121870b297e5aa50052b2545a9730da8ee6df52ec4331549ad39abe9aa46de",["Text"]="-----------------------------------\n-- ID: 18953\n-- Item: Beluga\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\n-- Old made up stuff from sql, fix when researched\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 10,\n        basePower      = math.randomInt(20, 25),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/berry_snow_cone.lua"]={["Path"]="scripts/items/berry_snow_cone.lua",["SHA256"]="272b9175371f612796106be6b9ec007a546fb8fecdafba14a8295faa21bb84b3",["Text"]="-----------------------------------\n-- ID: 5710\n-- Item: Berry Snowcone\n-- Food Effect: 5 Min, All Races\n-----------------------------------\n-- MP % 30 Cap 30\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 30)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 30)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/beryllium_bolt_quiver.lua"]={["Path"]="scripts/items/beryllium_bolt_quiver.lua",["SHA256"]="9d6cd263482391eda53b2720fa0598710e3953c83c19db6209875fa2a9ba38a9",["Text"]="-----------------------------------\n-- ID: 6428\n-- Beryllium Bolt Quiver\n-- When used, you will obtain one stack of Beryllium Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BERYLLIUM_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/beryllium_quiver.lua"]={["Path"]="scripts/items/beryllium_quiver.lua",["SHA256"]="f36e618e0604fbbb7f9e53248d31f1e4627d51348a3cffbc271f558289daea19",["Text"]="-----------------------------------\n-- ID: 6418\n-- Beryllium Quiver\n-- When used, you will obtain one stack of Beryllium Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BERYLLIUM_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/betta.lua"]={["Path"]="scripts/items/betta.lua",["SHA256"]="022560b0fd590023a6c30fee4e4ffcde83e6205ddc95960558d6da9937ec88ff",["Text"]="-----------------------------------\n-- ID: 5139\n-- Item: Betta\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bibiki_slug.lua"]={["Path"]="scripts/items/bibiki_slug.lua",["SHA256"]="ea7f6dd538335375e28bc0ab555abd59479d30b019702f28f81274978fd336c2",["Text"]="-----------------------------------\n-- ID: 5122\n-- Item: Bibiki Slug\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 4\n-- defense % 16\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.DEFP, 16)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bibikibo.lua"]={["Path"]="scripts/items/bibikibo.lua",["SHA256"]="c89c9eba9d8bcd05004763a37fa5171a862de554a1b2d783c47748eace9b8344",["Text"]="-----------------------------------\n-- ID: 4314\n-- Item: Bibikibo\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 1\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.MND, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bijou_glace.lua"]={["Path"]="scripts/items/bijou_glace.lua",["SHA256"]="41e4ca18f326ee8ea3fc59dfe5227b312d2a5c962226b81e8c0bc9523f87c344",["Text"]="-----------------------------------\n-- ID: 4269\n-- Item: Bijou Glace\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Magic % 13\n-- Magic Cap 90\n-- Magic Regen While Healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 13)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 90)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bird_egg.lua"]={["Path"]="scripts/items/bird_egg.lua",["SHA256"]="682e3e585b084b298480a636c587baf1fe9f06a8e6070bd20d067c57bba28b02",["Text"]="-----------------------------------\n-- ID: 4570\n-- Item: Bird Egg\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health 6\n-- Magic 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 6)\n    effect:addMod(xi.mod.FOOD_MP, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bismuth_bolt_quiver.lua"]={["Path"]="scripts/items/bismuth_bolt_quiver.lua",["SHA256"]="cec34fcb8dd1673dfb9984fe781b2d4771b140627b027d1b5c72fbfd99c9c00a",["Text"]="-----------------------------------\n-- ID: 6206\n-- Item: Bi. Bolt Quiver\n-- When used, you will obtain one stack of Bismuth Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BISMUTH_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/bismuth_bullet_pouch.lua"]={["Path"]="scripts/items/bismuth_bullet_pouch.lua",["SHA256"]="86d771e36cd19d5c21a276dff70f439555c65cd61230d97f2cf247b516266295",["Text"]="-----------------------------------\n-- ID: 6210\n-- Bi. Bull. Pouch\n-- When used, you will obtain one stack of Bismuth Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BISMUTH_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/black_bubble-eye.lua"]={["Path"]="scripts/items/black_bubble-eye.lua",["SHA256"]="b80c6f1019e1ca1a7385b20a34c674c8385fd4dc6d64a2b5fd30e66184e5b2e8",["Text"]="-----------------------------------\n-- ID: 4311\n-- Item: Black Bubble-Eye\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/black_chocobo_cap.lua"]={["Path"]="scripts/items/black_chocobo_cap.lua",["SHA256"]="ae2636e01806631d3e4dc0fc2d68a3659b58350930ec80349ef46d829de1c09b",["Text"]="-----------------------------------\n-- ID: 25585\n-- Black Chocobo Cap\n-- Enchantment: \"Teleport\" (Upper Jeuno Chocobo Stables)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.CHOCO_UPPER_JEUNO, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/black_curry_bun.lua"]={["Path"]="scripts/items/black_curry_bun.lua",["SHA256"]="408b40028d0676ec12a22e2fcdf08e89f9da76156e10051a7d4308794b0f6f22",["Text"]="-----------------------------------\n-- ID: 5758\n-- Item: black_curry_bun\n-- Food Effect: 30minutes, All Races\n-- https://wiki.ffo.jp/html/17769.html\n-----------------------------------\n-- DEX +2\n-- VIT +4\n-- INT +1\n-- Accuracy +5\n-- Ranged Accuracy +5\n-- Evasion +5\n-- DEF +15% (cap 180)\n-- Resist Sleep +3\n-- hHP +2\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nlocal dataTable =\n{\n    [ 1] = { xi.mod.DEX,            4,   3,   2 },\n    [ 2] = { xi.mod.VIT,            6,   5,   4 },\n    [ 3] = { xi.mod.INT,            3,   2,   1 },\n    [ 4] = { xi.mod.AGI,            2,   0,   0 },\n    [ 5] = { xi.mod.MND,            1,   0,   0 },\n    [ 6] = { xi.mod.HPHEAL,         6,   4,   2 },\n    [ 7] = { xi.mod.MPHEAL,         3,   2,   1 },\n    [ 8] = { xi.mod.FOOD_DEFP,     25,  20,  15 },\n    [ 9] = { xi.mod.FOOD_DEF_CAP, 200, 180, 180 },\n    [10] = { xi.mod.ACC,            7,   5,   5 },\n    [11] = { xi.mod.RACC,           7,   5,   5 },\n    [12] = { xi.mod.EVA,            7,   5,   5 },\n    [13] = { xi.mod.SLEEPRES,       5,   3,   3 }\n}\n\nitemObject.onEffectGain = function(target, effect)\n    for i = 1, #dataTable do\n        -- Get party factor.\n        local partySize = target:getPartySize()\n        local column = 4\n        if partySize >= 4 then\n            column = 2\n        elseif partySize >= 2 then\n            column = 3\n        end\n\n        effect:addMod(dataTable[i][1], dataTable[i][column])\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/black_curry_bun_+1.lua"]={["Path"]="scripts/items/black_curry_bun_+1.lua",["SHA256"]="28b6e18f4f5687ee89217172ba157bc0f8ceac068035baa43a5f29390f878ab1",["Text"]="-----------------------------------\n-- ID: 5764\n-- Item: black_curry_bun+1\n-- Food Effect: 60 min, All Races\n-----------------------------------\n-- TODO: Group effects\n-- Dexterity +4\n-- Vitality +6\n-- Intelligence +3\n-- Mind +1\n-- Accuracy +7\n-- Ranged Accuracy +7\n-- Evasion +7\n-- Defense +25% (cap 200)\n-- Resist Sleep +5\n-- hHP +6\n-- hMP +3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.VIT, 6)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.ACC, 7)\n    effect:addMod(xi.mod.RACC, 7)\n    effect:addMod(xi.mod.EVA, 7)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 200)\n    effect:addMod(xi.mod.SLEEPRES, 5)\n    effect:addMod(xi.mod.HPHEAL, 6)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/black_drop.lua"]={["Path"]="scripts/items/black_drop.lua",["SHA256"]="1f7fc082b496f004dfe171d9db99f88ba08f2316a704a480f2fd1cbd2705a4b1",["Text"]="-----------------------------------\n--  ID: 4265\n--  Item: Black Drop\n--  Transports the user to their Home Point\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 3600, origin = user })\n    target:warp()\nend\n\nreturn itemObject\n"},["scripts/items/black_eel.lua"]={["Path"]="scripts/items/black_eel.lua",["SHA256"]="74b8ccc097de4972173e9e0c8c2c9982db67e87b7dcff69f54e337f4a01dbad0",["Text"]="-----------------------------------\n-- ID: 4429\n-- Item: Black Eel\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-- Evasion 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/black_ghost.lua"]={["Path"]="scripts/items/black_ghost.lua",["SHA256"]="c2db2c83eb2e70d73bc0d2da70aef08d751ac5df5244898b940e59a7063eee90",["Text"]="-----------------------------------\n-- ID: 5138\n-- Item: Black Ghost\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 4\n-- Mind -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"}};
